`
import React, { useState } from 'react';
import { Sparkles, ShieldCheck, Gavel, Users, FileText, MapPin, Phone, Calendar, Mail, Send, Scale, X } from 'lucide-react';

const mockAttorneys = [
  {
    id: 1,
    name: 'Alex Mercer',
    title: 'Senior Corporate Counsel',
    avatar: 'https://images.unsplash.com/photo-1519480508934-b7f4f6a6c31c?w=150&q=80',
    initials: 'AM',
    practice: 'Corporate M&A & Venture Capital',
    phone: '+1 (555) 234-5678',
    email: 'alex.mercer@rautlaw.com',
    timezone: 'Pacific Standard Time',
    bio: 'Alex specializes in high-growth startup acquisitions and private equity investments. With a knack for due diligence and negotiation, he ensures seamless transactions and shareholder value.'
  },
  {
    id: 2,
    name: 'Elena Volkov',
    title: 'Criminal Defense Advocate',
    avatar: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&q=80',
    initials: 'EV',
    practice: '白领犯罪辩护 & 企业合规',
    phone: '+1 (555) 345-6789',
    email: 'elena.volkov@rautlaw.com',
    timezone: 'Eastern Standard Time',
    bio: 'Elena defends high-profile executives and professionals facing white-collar charges. Her strategic approach and deep understanding of regulatory landscapes safeguard her clients\' reputations and careers.'
  },
  {
    id: 3,
    name: 'Miguel Santos',
    title: 'Intellectual Property Partner',
    avatar: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150&q=80',
    initials: 'MS',
    practice: 'Patent Filing & Trademark Protection',
    phone: '+1 (555) 456-7890',
    email: 'miguel.santos@rautlaw.com',
    timezone: 'Central European Time',
    bio: 'Miguel is the go-to IP attorney for emerging tech startups. His expertise in global filing strategies and enforcement actions keeps clients ahead of potential infringements.'
  }
];

export default function Attorneys() {
  const [activeFilter, setActiveFilter] = useState('All');
  const [isLoading, setIsLoading] = useState(false);
  const [selectedAttorney, setSelectedAttorney] = useState(null);

  const filteredAttorneys = mockAttorneys.filter(attorney => {
    if (activeFilter === 'All') return true;
    return attorney.practice.toLowerCase() === activeFilter.toLowerCase();
  });

  const handleSelect = (attorney) => {
    setSelectedAttorney(attorney);
    setIsLoading(true);
    setTimeout(() => setIsLoading(false), 600);
  };

  return (
    <div className="w-full bg-slate-950 text-slate-100 font-sans antialiased min-h-[800px]">
      {/* Gradient Decorative Top Bar */}
      <div className="fixed top-0 left-0 right-0 h-32 bg-gradient-to-b from-indigo-900 via-purple-900 to-transparent" />

      {/* Main Content */}
      <div className="relative mx-auto max-w-7xl px-6 pb-24 sm:px-8 lg:px-12">
        {/* Header Section */}
        <div className="mb-16 flex flex-col items-center justify-center space-y-4 sm:space-y-6">
          <h2 className="text-3xl font-bold tracking-tight text-slate-100 sm:text-4xl">Meet Your Trusted Advisors</h2>
          <p className="text-base text-slate-400">Dedicated legal minds shaping your company's future.</p>
        </div>

        {/* Filter Bar */}
        <div className="grid grid-cols-2 gap-4 sm:grid-cols-4 sm:gap-6 mb-12">
          {['All', 'Corporate & M&A', 'Intellectual Property', 'Criminal Defense'].map((name) => (
            <button
              key={name}
              onClick={() => setActiveFilter(name)}
              className="flex items-center justify-center gap-2 px-3 py-2 rounded-xl bg-white/5 border border-white/10 text-slate-300 hover:text-white hover:bg-white/10 transition-colors active:scale-95"
              style={{ backgroundColor: activeFilter === name ? 'rgba(255,255,255,0.1)' : 'transparent' }}
            >
              {name}
              {activeFilter === name && <span className="w-3 h-1.5 bg-indigo-500 rounded-full" />}
            </button>
          ))}
        </div>

        {/* Attorney Cards */}
        <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {filteredAttorneys.map((attorney) => (
            <div
              key={attorney.id}
              className="group relative overflow-hidden rounded-2xl border border-white/10 bg-slate-900/90 backdrop-blur-xl transition-all duration-300 hover:scale-[1.02] hover:shadow-2xl"
            >
              {/* Top Gradients */}
              <div className="absolute inset-0 bg-gradient-to-br from-indigo-600/20 to-purple-600/10" />

              {/* Hover Scale & Shadow */}
              <div className="absolute -top-12 -right-12 -bottom-12 -left-12 bg-gradient-to-br from-white/10 via-white/5 to-white/0 opacity-0 transition-all duration-300 group-hover:opacity-50" />

              {/* Avatar & Initials */}
              <div className="relative h-48 w-full bg-slate-900 flex items-center justify-center rounded-t-2xl bg-cover bg-center transition-all duration-300 group-hover:scale-[1.05] group-hover:bg-white/[0.05]">
                {attorney.avatar ? (
                  <img src={attorney.avatar} alt={attorney.name} className="w-full h-full object-cover rounded-2xl" />
                ) : (
                  <div className="bg-slate-950/40 backdrop-blur-xl flex items-center justify-center rounded-xl p-3 text-slate-400">
                    {attorney.initials}
                  </div>
                )}
              </div>

              {/* Info Section */}
              <div className="p-6">
                <div className="mb-4 flex flex-col justify-between">
                  <div className="flex items-center justify-between">
                    <h3 className="text-xl font-semibold text-slate-100">{attorney.name}</h3>
                    <span className="inline-flex items-center gap-1 text-xs text-slate-400">{attorney.title}</span>
                  </div>
                  <span className="text-xs text-slate-400">{attorney.timezone}</span>
                </div>
                <p className="mt-4 text-sm text-slate-400">{attorney.practice}</p>
                <ul className="mt-6 flex flex-wrap gap-3">
                  {['scale', 'gavel', 'shield'].map((iconName) => (
                    <li key={iconName} className="text-slate-400">
                      <div className="flex items-center gap-1 text-[0.75em]">
                        <div className={`w-3.5 h-3.5 rounded-full bg-amber-400/20 text-amber-400 group-hover:bg-amber-500/30 transition-colors duration-300 ${`border border-white/10 p-0.5 rounded-full`}`}>
                          <div className={`w-2 h-2 rounded-full bg-white transition-transform duration-300 group-hover:w-3 group-hover:h-3`}>
                            <div className={`w-2 h-2 rounded-full bg-white transition-transform duration-300 group-hover:w-3 group-hover:h-3`}>
                              {iconName === 'scale' && <Scale className="w-3.5 h-3.5 text-slate-400" />}
                              {iconName === 'gavel' && <Gavel className="w-3.5 h-3.5 text-slate-400" />}
                              {iconName === 'shield' && <ShieldCheck className="w-3.5 h-3.5 text-slate-400" />}
                            </div>
                          </div>
                        </div>
                      </div>
                    </li>
                  ))}
                </ul>
              </div>

              {/* Contact & Book Call Buttons */}
              <div className="absolute bottom-6 left-6 right-6 flex flex-col gap-2 p-4 bg-slate-900/80 backdrop-blur-xl border border-white/10 rounded-2xl shadow-lg transition-all duration-300">
                <div className="flex flex-col gap-1 text-center">
                  <button
                    onClick={() => handleSelect(attorney)}
                    className="inline-flex items-center gap-2 rounded-xl bg-white/5 py-2 px-4 text-sm font-medium text-slate-300 hover:bg-white/10 transition-colors"
                  >
                    <Mail className="w-4 h-4 text-slate-400" /> Contact
                  </button>
                  <button
                    className="inline-flex items-center gap-2 rounded-xl bg-white/5 py-2 px-4 text-sm font-medium text-slate-300 hover:bg-white/10 transition-colors"
                  >
                    <Calendar className="w-4 h-4 text-slate-400" /> Schedule
                  </button>
                </div>
                {selectedAttorney && (
                  <div className="absolute -top-24 left-1/2 -translate-x-1/2 w-96 rounded-2xl bg-white/5 p-6 backdrop-blur-xl border border-white/10 shadow-2xl transition-all duration-300">
                    <div className="relative flex flex-col">
                      <div className="flex items-center justify-between mb-6">
                        <h4 className="text-lg font-medium text-slate-100">{selectedAttorney.name}</h4>
                        <button
                          onClick={() => setSelectedAttorney(null)}
                          className="text-slate-400 hover:text-slate-300 transition-colors"
                        >
                          <X className="w-5 h-5" />
                        </button>
                      </div>
                      <div className="flex flex-col gap-4">
                        <div className="flex items-center gap-3">
                          <div className="flex flex-col items-center gap-1 text-xs">
                            <span className="text-slate-400">Phone:</span>
                            <span className="text-slate-300">{selectedAttorney.phone}</span>
                          </div>
                          <div className="flex flex-col items-center gap-1 text-xs">
                            <span className="text-slate-400">Email:</span>
                            <span className="text-slate-300">{selectedAttorney.email}</span>
                          </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                          <div className="flex items-center gap-3">
                            <div className="flex flex-col items-center gap-1 text-xs">
                              <span className="text-slate-400">Timezone:</span>
                              <span className="text-slate-300">{selectedAttorney.timezone}</span>
                            </div>
                          </div>
                        </div>
                      </div>
                      <div className="mt-6 flex items-center justify-center gap-3">
                        <button
                          onClick={() => {
                            setSelectedAttorney(null);
                            setTimeout(() => {
                              navigator.clipboard.writeText(selectedAttorney.email);
                            }, 100);
                          }}
                          className="inline-flex items-center gap-2 rounded-xl bg-white/10 px-6 py-3 text-sm font-medium text-slate-300 border border-white/10 hover:bg-white/20 transition-colors"
                        >
                          <Mail className="w-4 h-4" /> Copy Email
                        </button>
                        <button
                          onClick={() => {
                            setSelectedAttorney(null);
                            setTimeout(() => {
                              navigator.clipboard.writeText(selectedAttorney.phone);
                            }, 100);
                          }}
                          className="inline-flex items-center gap-2 rounded-xl bg-white/10 px-6 py-3 text-sm font-medium text-slate-300 border border-white/10 hover:bg-white/20 transition-colors"
                        >
                          <Phone className="w-4 h-4" /> Copy Phone
                        </button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

`src/components/Faq.jsx`

import React, { useState } from 'react';
import { ChevronDown, ShieldCheck, ArrowRight, HelpCircle, Sparkles, FileText, CheckCircle2, X } from 'lucide-react';

const questions = [
  {
    id: 1,
    title: 'How does RautLaw ensure client data confidentiality?',
    content: 'We employ advanced encryption protocols and multi-factor authentication. All data is stored in tier-1 secure data centers with 24/7 surveillance.'
  },
  {
    id: 2,
    title: 'What is the average response time for case inquiries?',
    content: 'Within 1 business hour. For urgent cases, our on-call partners respond within 15 minutes.'
  },
  {
    id: 3,
    title: 'Do you offer flexible payment plans for businesses?',
    content: 'Yes, we can structure tiered billing packages and interest-free deferred payment terms. Contact us for a custom offer.'
  },
  {
    id: 4,
    title: 'Are your legal services compatible with international clients?',
    content: 'Absolutely. Our legal advisors are multilingual and familiar with global compliance standards, serving clients across the EU, USA, and APAC.'
  },
  {
    id: 5,
    title: 'How do you handle legal disputes and challenges proactively?',
    content: 'We conduct a risk assessment at intake and maintain an active litigation tracking system. Proactive briefs and contingency strategies are always part of our standard protocol.'
  }
];

export default function Faq() {
  const [expanded, setExpanded] = useState(new Array(questions.length).fill(false));

  const toggleAccordion = (index) => {
    setExpanded((prev) => {
      const newExpanded = [...prev];
      newExpanded[index] = !newExpanded[index];
      return newExpanded;
    });
  };

  return (
    <div className="w-full max-w-7xl mx-auto p-6 sm:p-8 bg-slate-950 text-slate-100 font-sans">
      {/* Decorative Gradient Background */}
      <div className="absolute -top-48 left-1/2 -translate-x-1/2 w-96 h-96 bg-gradient-to-tr from-indigo-500/20 via-purple-500/10 to-transparent opacity-50 pointer-events-none" />

      <div className="relative z-10 text-center">
        <h2 className="text-3xl sm:text-4xl lg:text-5xl font-bold tracking-tight text-slate-100 sm:text-left mb-6">
          <span className="inline bg-gradient-to-r from-indigo-400 via-purple-400 to-rose-400 text-transparent bg-clip-text animate-pulse">FAQ</span>
        </h2>
        <p className="text-slate-400 max-w-md mx-auto mb-12 text-lg sm:text-xl font-medium text-center">
          Our comprehensive legal guidance, from initial consultations to resolution.
        </p>
      </div>

      <div className="w-full max-w-2xl mx-auto grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 p-6 rounded-3xl bg-white/5 border border-white/10 shadow-2xl backdrop-blur-xl">
        {questions.map((faq, i) => (
          <div key={faq.id} className="relative group rounded-2xl bg-white/10 border border-white/5 p-6 transition-all duration-300 hover:scale-[1.015] hover:border-white/10 hover:bg-white/20">
            <div className="absolute -inset-1.5 bg-white/5 rounded-2xl border border-white/5" />
            <div className="relative mb-6">
              <button
                onClick={() => toggleAccordion(i)}
                className="w-full p-3 flex items-start gap-3 rounded-xl bg-white/5 border border-white/5 transition-all duration-200 hover:bg-white/10 hover:border-white/10 active:scale-[0.98]"
              >
                <div className="text-slate-300 flex-1">
                  <h4 className="font-semibold text-slate-200 tracking-tight mb-1">{faq.title}</h4>
                  <p className="text-slate-400 text-sm">{faq.id === 1 ? 'Data Security Compliance' : 'Standard Client Service'}</p>
                </div>
                <div className="flex-none rounded-lg bg-white/5 p-1 text-slate-300 transition-transform duration-300 group-hover:text-indigo-400">
                  {expanded[i] ? <ChevronDown className="w-5 h-5" /> : <ChevronDown className="w-5 h-5 transform rotate-180" />}
                </div>
              </button>
              {expanded[i] && (
                <div className="p-4 bg-white/5 border border-white/5 rounded-2xl mt-4">
                  <div className="space-y-4">
                    {faq.content.split('\n').map((line, idx) => (
                      <p key={idx} className="text-slate-400 text-sm tracking-wide">
                        {line}
                      </p>
                    ))}
                  </div>
                </div>
              )}
            </div>
            <div className="absolute -bottom-3 -right-3 flex items-center gap-2 text-slate-400 group-hover:text-white transition-colors duration-200">
              <Sparkles className="w-4 h-4 animate-pulse" />
              <p className="text-xs font-medium tracking-wide uppercase">Read More</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

