import React, { useState } from 'react';
import { Sparkles, Gavel, ShieldCheck, Users, Mail, ChevronRight, ArrowUpRight, BarChart4, CheckCircle2, Sparkles as SparklesIcon } from 'lucide-react';

const SCALE_ANIMATION = [
  { scale: 'scale-0', duration: 400 },
  { scale: 'scale-100', duration: 800 },
  { scale: 'scale-0', duration: 400 },
];

const INITIAL_SCALES = [
  { id: 1, label: 'E-Discovery & Cybersecurity', value: 92, icon: Sparkles, gradient: 'from-indigo-500/20 via-purple-500/20 to-pink-500/20' },
  { id: 2, label: 'Intellectual Property', value: 88, icon: Sparkles, gradient: 'from-blue-500/20 via-indigo-500/20 to-purple-500/20' },
