  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 sm:p-12 relative overflow-hidden">
      {/* Background Glows */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full max-w-md flex flex-col items-start justify-between gap-6">
        {scales.map((scale) => (
          <div key={scale.id} className="flex items-center gap-2 p-3 rounded-xl bg-white/5 backdrop-blur-xl border border-white/10 text-slate-400 text-sm font-medium">
            <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium bg-white/20 border border-white/10 ${scale.gradient}`}>
              <scale.icon className="w-3 h-3 text-white" />
              {scale.label}
            </span>
            <span className="text-slate-500">{scale.value}%</span>
          </div>
        ))}
      </div>

      {/* Main Hero Section */}
      <div className="relative w-full max-w-7xl mx-auto">
        <div className="absolute top-1/4 left-1/4 w-3/4 h-3/4 bg-slate-900/60 backdrop-blur-xl rounded-2xl pointer-events-none" />

        <div className="relative z-10 p-8 sm:p-12 bg-white/5 border border-white/10 rounded-2xl shadow-2xl backdrop-blur-xl text-slate-200 flex flex-col justify-between h-full">
          {/* Gradient Decorative Stripe */}
          <div className="absolute bottom-0 left-0 right-0 h-2 bg-gradient-to-r from-indigo-500/10 via-purple-500/10 to-pink-500/10" />

          {/* Header Row */}
          <div className="mb-8 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
            <div className="flex flex-col sm:flex-row gap-4">
              <div className="relative flex flex-col items-center justify-center w-24 sm:w-32 h-24 sm:h-32 rounded-2xl bg-white/5 border border-white/10 shadow-inner group">
                <div className="absolute inset-0 bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 rounded-2xl opacity-50 group-hover:opacity-75 transition-opacity duration-300" />
                <div className="relative p-4 flex flex-col items-center justify-center">
                  <h1 className="text-3xl sm:text-4xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-indigo-400 via-purple-400 to-pink-400 mb-2">Raut Law Firm</h1>
                  <p className="text-sm sm:text-base text-slate-400 tracking-wide">Premier Legal Solutions for Business & Entrepreneurs</p>
                </div>
              </div>
              {/* Decorative Icon Stack */}
              <div className="flex flex-col sm:flex-row gap-3">
                <div className="w-12 h-12 sm:w-16 sm:h-16 bg-slate-900/30 rounded-2xl flex items-center justify-center shadow-inner transition-all duration-300 hover:scale-105 hover:bg-slate-900/40">
                  <Sparkles className="w-5 h-5 text-indigo-400" />
                </div>
                <div className="w-12 h-12 sm:w-16 sm:h-16 bg-slate-900/30 rounded-2xl flex items-center justify-center shadow-inner transition-all duration-300 hover:scale-105 hover:bg-slate-900/40">
                  <ShieldCheck className="w-5 h-5 text-emerald-400" />
                </div>
              </div>
            </div>
            {/* CTA Buttons */}
            <div className="flex gap-4">
              <button className="px-6 py-3 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-slate-100 font-semibold text-sm shadow-lg transition-all duration-200 border border-indigo-600/30 active:scale-95">
                Schedule a Consultation
              </button>
              <button className="px-6 py-3 rounded-xl bg-white/10 border border-white/20 text-slate-400 hover:text-slate-100 hover:bg-white/20 font-semibold text-sm transition-colors duration-200">
                Learn More <ChevronRight className="w-3 h-3 ml-2" />
              </button>
            </div>
          </div>

          {/* Scale Bar Animation */}
          <div className="relative mb-8">
            {isAnimating ? scales.map((scale, i) => (
              <div key={scale.id} className="relative mb-4 w-3/4 sm:w-1/2 flex items-center justify-between">
                <div className="flex items-center gap-2 px-3 py-1 rounded-xl bg-white/5 border border-white/10 text-slate-400 text-xs font-medium">
                  <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium bg-white/20 border border-white/10">
                    <scale.icon className="w-3 h-3 text-white" />
                    {scale.label}
                  </span>
                  <span className="text-slate-500">{scale.value}%</span>
                </div>
                <div className="w-full bg-white/5 rounded-xl border border-white/10 flex items-center justify-between px-3">
                  <div className={`w-24 sm:w-32 h-1.5 bg-white/20 rounded-lg animate-pulse`}>
                    <div className={`h-full bg-indigo-600 rounded-lg w-0 animate-[progress-4s_linear_infinite] ${scale.id === 1 ? 'w-full' : 'w-0'}`}></div>
                  </div>
                  <div className={`w-24 sm:w-32 h-1.5 bg-white/20 rounded-lg animate-pulse`}>
                    <div className={`h-full bg-indigo-600 rounded-lg w-0 animate-[progress-4s_linear_infinite] ${scale.id === 2 ? 'w-full' : 'w-0'}`}></div>
                  </div>
                  <div className={`w-24 sm:w-32 h-1.5 bg-white/20 rounded-lg animate-pulse`}>
                    <div className={`h-full bg-indigo-600 rounded-lg w-0 animate-[progress-4s_linear_infinite] ${scale.id === 3 ? 'w-full' : 'w-0'}`}></div>
                  </div>
                </div>
              </div>
            )) : (
              scales.map((scale, i) => {
                const { scale: scaleStyle, duration } = SCALE_ANIMATION[i % SCALE_ANIMATION.length];
                return (
                  <div key={scale.id} className="relative mb-4 w-3/4 sm:w-1/2 flex items-center justify-between">
                    <div className="flex items-center gap-2 px-3 py-1 rounded-xl bg-white/5 border border-white/10 text-slate-400 text-xs font-medium">
                      <span className="inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium bg-white/20 border border-white/10">
                        <scale.icon className="w-3 h-3 text-white" />
                        {scale.label}
                      </span>
                      <span className="text-slate-500">{scale.value}%</span>
                    </div>
                    <div className="w-full bg-white/5 rounded-xl border border-white/10 flex items-center justify-between px-3">
                      <div className={`w-24 sm:w-32 h-1.5 bg-white/20 rounded-lg ${scaleStyle}`}>
                        <div className={`h-full bg-indigo-600 rounded-lg w-full transition-transform duration-${duration}`}>
                          <div className="absolute bottom-0 left-0 h-1.5 w-full bg-white/20" />
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })
            )}
          </div>

          {/* Call-to-Action Button Row */}
          <div className="flex flex-col sm:flex-row justify-between items-end sm:items-center gap-4 mb-8">
            <button onClick={handleStartAnimation} className="px-6 py-3 rounded-xl bg-emerald-600 hover:bg-emerald-700 text-slate-100 font-semibold text-sm shadow-lg transition-all duration-200 border border-emerald-600/30 active:scale-95">
              Discover How We Scale Justice
            </button>
            <div className="flex items-center gap-2">
              <div className="w-12 h-12 rounded-xl bg-slate-900/30 flex items-center justify-center shadow-inner transition-all duration-300 hover:scale-105 hover:bg-slate-900/40">
                <Sparkles className="w-6 h-6 text-emerald-400" />
              </div>
              <span className="text-slate-400 text-sm">Ready to boost your legal outcomes?</span>
            </div>
          </div>

          {/* Decorative Gradient Glow */}
          <div className="absolute bottom-0 left-0 right-0 h-1 bg-gradient-to-r from-indigo-500/10 via-purple-500/10 to-pink-500/10" />
        </div>
      </div>
    </div>
  );
}
